additional({id:'W-R-001',platform:'web',severity:'P2',category:'accessibility',criterion:'WCAG 1.4.3: normal text >=4.5:1',title:'Supporting operational text falls below contrast threshold',issue:'Computed CSS Color 4 measurements show voyage metadata 2.4044:1, EDI field labels 2.5108:1, dashboard lane 2.5573:1 and request ID 2.6282:1. These meaningful labels are normal small text. Decorative separators/icons are excluded. Login-only Lighthouse pass does not cover these authenticated screens.',evidence:[{file:'apps/web/src/components/ManifestsView.tsx',line:233},{file:'apps/web/src/components/EDIView.tsx',line:283},{file:'apps/web/src/components/DashboardView.tsx',line:241},{file:'apps/web/src/components/AuditsView.tsx',line:78}],measurements:{voyage:2.4044,edi:2.5108,lane:2.5573,requestId:2.6282,threshold:4.5},runtime_artifacts:['audit/raw/baseline/web/contrast-color4-results.json','audit/raw/baseline/web/manifests-1440-measure.json','audit/raw/baseline/web/edi-1440-measure.json'],recommendedFix:'Use a darker semantic supporting-text token on these light surfaces; preserve status colors and layout. Measure each resulting foreground/background pair.',fix_proposal:'/* A semantic alias within the existing Tailwind palette. */\n.text-supporting {\n  @apply text-slate-600;\n}\n/* Apply to meaningful field labels and metadata; verify >= 4.5:1. */',verify:['Recompute the four named pairs at 375/768/1440px; all >=4.5:1.','Validate representative rendered pixels and exclude decoration, obscured background content and unsupported effects.'],heuristic_ids:['H4','H8']});
additional({id:'W-R-002',platform:'web',severity:'P2',category:'accessibility',criterion:'WCAG 2.4.7 Focus Visible',title:'Yard map search has no visible keyboard focus',issue:'Keyboard focus reaches the map search (:focus-visible=true), but input outline is none, shadow is none and its wrapper has no outline/shadow. Source removes the outline; global focus styling only covers buttons and links.',evidence:[{file:'apps/web/src/components/yard/YardSiteMap.tsx',line:109},{file:'apps/web/src/index.css',line:7}],runtime_artifacts:['audit/raw/baseline/web/yard-search-keyboard-focus.json','audit/screenshots/baseline/web/yard-search-keyboard-focus.jpg'],recommendedFix:'Add focus-visible ring to the existing input or focus-within ring to its current wrapper.',fix_proposal:'<input\n  aria-label="Tìm vị trí hoặc container trên bản đồ"\n  className="min-w-0 flex-1 outline-none focus-visible:ring-2 focus-visible:ring-blue-600"\n  value={query}\n  onChange={(event) => setQuery(event.target.value)}\n/>',verify:['Shift+Tab then Tab into map search; a visible ring appears without layout shift.','Search remains keyboard usable and the ring is not clipped.'],heuristic_ids:['H4','H7']});
additional({id:'W-R-003',platform:'web',severity:'P2',category:'tokens',criterion:'Project checklist: typography values in tokens',title:'Repeated metadata sizes bypass the type token scale',issue:'Dashboard and Manifest repeat arbitrary 9/10/11px Tailwind values. These are local literals outside the named default type scale, making changes to metadata/action roles inconsistent. Named Tailwind spacing/color utilities are treated as tokens; literals inside a token definition are not findings.',evidence:[{file:'apps/web/src/components/DashboardView.tsx',line:334},{file:'apps/web/src/components/DashboardView.tsx',line:241},{file:'apps/web/src/components/ManifestsView.tsx',line:235}],recommendedFix:'Centralize the existing small type roles and apply their aliases; keep the current visual values initially and remove scattered duplicate literals.',fix_proposal:'@theme {\n  --text-metadata: 0.625rem;\n  --text-caption: 0.6875rem;\n}\n/* Replace repeated text-[10px]/text-[11px] with semantic aliases. */',verify:['No repeated arbitrary font-size literals remain in the affected metadata roles.','Screenshots show equivalent hierarchy before/after; scale changes need separate review.'],heuristic_ids:['H4']});
additional({id:'W-R-004',platform:'web',severity:'P3',category:'layout',criterion:'Project heading line-height 1.1-1.3',title:'Default heading line heights exceed the project rubric',issue:'Measured desktop shell h1 is16px/24px=1.5. The current heading utilities inherit loose line heights rather than the requested1.1-1.3. This is a rubric consistency gap, not a WCAG failure or a demonstrated task blocker.',evidence:[{file:'apps/web/src/components/Header.tsx',line:1}],runtime_artifacts:['audit/raw/baseline/web/dashboard-1440-measure.json'],measurements:{fontSize:16,lineHeight:24,ratio:1.5,expected:[1.1,1.3]},recommendedFix:'Define a heading role with an appropriate line-height and check wrapped localized headings; retain current font sizes and hierarchy.',fix_proposal:'.type-heading {\n  line-height: 1.25;\n}\n/* Apply only to headings, then check multi-line Vietnamese labels. */\n/* Body text retains its readable line-height. */',verify:['Heading computed line-height is1.1-1.3 where the role applies.','Long headings do not overlap or clip at all tested widths.'],heuristic_ids:['H4']});
additional({id:'M-013',platform:'mobile',severity:'P2',category:'tokens',criterion:'Project checklist: semantic color, spacing and type tokens',title:'Shared header/layout repeat values outside existing tokens',issue:'AppHeader embeds scanner red/white colors and8/10/12px type values. Shared ScreenLayout uses14dp padding/gap and10/9dp input padding despite a4/8 spacing scale. Theme definitions may contain literals; this finding concerns consumer components bypassing them. It does not require a new visual design.',evidence:[{file:'apps/mobile/src/components/AppHeader.tsx',line:96},{file:'apps/mobile/src/components/AppHeader.tsx',line:157},{file:'apps/mobile/src/components/ScreenLayout.tsx',line:53},{file:'apps/mobile/src/theme/spacing.ts',line:1}],recommendedFix:'Add named roles for intentional values, reuse existing typography/spacing roles where appropriate, and use contrast-safe fill/on-fill tokens coordinated with M-002.',fix_proposal:'const scanStyle = {\n  backgroundColor: theme.colors.dangerButton,\n  paddingHorizontal: theme.spacing.sm,\n};\nconst scanText = { ...theme.typography.captionBold, color: theme.colors.onDangerButton };\n// Add the named fill/on-fill roles to Theme and both palettes first.',verify:['Affected consumers reference named tokens; literals are limited to token definitions and documented geometry.','Preserve existing layout and test both themes plus320dp/font scale1.5.'],heuristic_ids:['H4']});
