const imageIndex=['# Danh mục ảnh baseline — '+date,'','Ảnh native giữ nguyên, không dựng lại. Những case chưa xác nhận danh tính màn được ghi UNKNOWN trong coverage; file ảnh không tự chứng minh thao tác thành công.','', '| Platform | Case / screenshot | Coverage status |','|---|---|---|'];
for(const platform of ['web','mobile']){const dir=`audit/screenshots/baseline/${platform}`;for(const name of fs.readdirSync(path.join(repo,dir)).filter(x=>/\.(png|jpg)$/.test(x)).sort()){const id=name.replace(/\.(png|jpg)$/,'');const cc=coverage.find(x=>x.caseId===id||`${x.screen}-${x.viewport}`===id||x.screen===id);imageIndex.push(`| ${platform} | ${link(dir+'/'+name,id)} | ${cc?.status||'Capture bổ sung / không dùng để khẳng định coverage'} |`);}}
fs.writeFileSync(path.join(root,'screenshots/baseline/index.md'),imageIndex.join('\n')+'\n');
